import{_ as d,C as r,o as e,c as n,a2 as l,b as s,w as o,a as E,E as i,a3 as A}from"./chunks/framework.BODD28Fk.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",x=JSON.parse('{"title":"회사 인장 관리 (관리자 가이드)","description":"","frontmatter":{},"headers":[],"relativePath":"authority/company-seal.md","filePath":"authority/company-seal.md","lastUpdated":1793459614000}'),g={name:"authority/company-seal.md"};function c(B,t,m,f,_,y){const a=r("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h1 id="회사-인장-관리-관리자-가이드" tabindex="-1">회사 인장 관리 (관리자 가이드) <a class="header-anchor" href="#회사-인장-관리-관리자-가이드" aria-label="Permalink to &quot;회사 인장 관리 (관리자 가이드)&quot;">​</a></h1><p>법인인감, 사용인감, 프로젝트 직인, 부서인감 등 회사의 공식 도장을 시스템에 정식 등록하고, 각 인장별 허용 전결 자격(결재 규정)을 사전에 설정하여 인장 오남용과 월권을 원천 통제하는 관리자 전용 화면입니다.</p><ul><li><strong>위치</strong>: <ul><li>Django Admin 백오피스: <code>회사 및 조직 관리 &gt; 회사 인장</code> (<code>/admin/company/companyseal/</code>)</li><li>또는 <code>회사 정보 관리</code> 상세 페이지 내 <code>회사 인장</code> 인라인 목록</li></ul></li><li><strong>관리 주체</strong>: 본사 관리부서(경영지원본부, 총무팀, 법무팀) 담당자 및 최고 관리자 (<code>SuperUser</code>)</li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="회사 인장 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/company-seal.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>회사의 도장과 서명은 대외적인 법적 권리·의무를 발생시키는 핵심 법률 자산입니다. 따라서 일반 사용자가 임의로 이미지를 등록하거나 사용할 수 없으며, 본사 관리부서의 정식 검증 및 등록 절차를 통해서만 시스템에 편입됩니다. 인장마다 허용되는 최소 결재 직책(전결 기준)과 연동 결재선을 지정하여, 공문서 발송 시 시스템이 결재선을 자동으로 산출하고 무단 날인을 차단합니다.</p>',6)),(e(),s(A,null,{default:o(()=>[i(a,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%ED%98%84%EC%9E%A5%20%2F%20%EC%82%AC%EC%97%85%EB%B3%B8%EB%B6%80%3Cbr%2F%3E(%EC%9D%B8%EC%9E%A5%20%EC%82%AC%EC%9A%A9%20%EB%B6%80%EC%84%9C)%22%5D%20--%3E%7C%EC%9D%B8%EC%9E%A5%20%EB%93%B1%EB%A1%9D%20%EC%9A%94%EC%B2%AD%7C%20B%5B%22%EB%B3%B8%EC%82%AC%20%EA%B4%80%EB%A6%AC%EB%B6%80%EC%84%9C%3Cbr%2F%3E(%EC%B4%9D%EB%AC%B4%C2%B7%EB%B2%95%EB%AC%B4%C2%B7%EA%B2%BD%EC%98%81%EC%A7%80%EC%9B%90)%22%5D%0A%20%20%20%20B%20--%3E%7C1.%20%EC%A0%95%EC%8B%9D%20%EC%9D%B8%EC%9E%A5%20%EB%A7%88%EC%8A%A4%ED%84%B0%20%EB%93%B1%EB%A1%9D%7C%20C%7B%222.%20%EC%9D%B8%EC%9E%A5%20%EC%A2%85%EB%A5%98%20%26%20%EC%A0%84%EA%B2%B0%20%EA%B8%B0%EC%A4%80%20%EC%84%A4%EC%A0%95%22%7D%0A%20%20%20%20C%20--%20%22%EB%B2%95%EC%9D%B8%EC%9D%B8%EA%B0%90%20%2F%20%EC%82%AC%EC%9A%A9%EC%9D%B8%EA%B0%90%22%20--%3E%20D%5B%22%EB%8C%80%ED%91%9C%EC%9D%B4%EC%82%AC%20%EA%B2%B0%EC%9E%AC%20%ED%95%84%EC%88%98%3Cbr%2F%3E(%EC%A0%84%EA%B2%B0%20%EB%B6%88%EA%B0%80%20%ED%86%B5%EC%A0%9C)%22%5D%0A%20%20%20%20C%20--%20%22%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EC%A7%81%EC%9D%B8%20%2F%20%EB%B6%80%EC%84%9C%EC%9D%B8%EA%B0%90%22%20--%3E%20E%5B%22%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EC%B1%85%EC%9E%84%EC%9E%90%20%2F%20%EB%B6%80%EC%84%9C%EC%9E%A5%20%EC%A0%84%EA%B2%B0%20%ED%97%88%EC%9A%A9%3Cbr%2F%3E(%EC%A0%84%EA%B2%B0%20%EC%A7%81%EC%B1%85%20%EB%B0%8F%20%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EB%A7%A4%ED%95%91)%22%5D%0A%20%20%20%20D%20%26%20E%20--%3E%20F%5B%22%EA%B3%B5%EB%AC%B8%20%EB%B0%9C%EC%86%A1%20%EC%8B%9C%20%EC%9E%90%EB%8F%99%20%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EC%82%B0%EC%B6%9C%3Cbr%2F%3E%26%20%EC%9D%B8%EC%9E%A5%20%EC%98%A4%EB%82%A8%EC%9A%A9%20%EC%9B%90%EC%B2%9C%20%EC%B0%A8%EB%8B%A8%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능-및-등록-가이드" tabindex="-1">주요 기능 및 등록 가이드 <a class="header-anchor" href="#주요-기능-및-등록-가이드" aria-label="Permalink to &quot;주요 기능 및 등록 가이드&quot;">​</a></h2><p>관리부서에서 신규 인장을 등록할 때 설정해야 하는 핵심 필드 기준표입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">영문 필드</th><th style="text-align:left;">상세 설명 및 설정 가이드</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>소속 회사</strong></td><td style="text-align:left;"><code>company</code></td><td style="text-align:left;">해당 인장이 귀속되는 소속 법인을 선택합니다.</td></tr><tr><td style="text-align:left;"><strong>인장 종류</strong></td><td style="text-align:left;"><code>seal_type</code></td><td style="text-align:left;">• <strong>법인인감 (<code>CORP_SEAL</code>)</strong>: 대표이사 직인 (원칙적 전결 불가)<br>• <strong>사용인감 (<code>USAGE_SEAL</code>)</strong>: 토지매매, 분양계약 등 특정 용도 지정 인감<br>• <strong>부서/프로젝트 직인 (<code>DEPT_SEAL</code>)</strong>: 사업본부장, 현장소장 명의 직인<br>• <strong>직인생략 (<code>OMIT</code>)</strong>: 단순 통지용 문서</td></tr><tr><td style="text-align:left;"><strong>인장 명칭</strong></td><td style="text-align:left;"><code>name</code></td><td style="text-align:left;">사용자가 쉽게 식별할 수 있는 공식 명칭 (예: <em>대표이사 법인인감</em>, <em>고성 아야진 현장소장 직인</em>)</td></tr><tr><td style="text-align:left;"><strong>지정 용도/범위</strong></td><td style="text-align:left;"><code>purpose</code></td><td style="text-align:left;">해당 인장의 사용 제한 범위 (예: <em>사업부지 토지매매계약 체결 전용</em>, <em>분양 계약 및 옵션 체결 전용</em>)</td></tr><tr><td style="text-align:left;"><strong>인장 이미지</strong></td><td style="text-align:left;"><code>seal_image</code></td><td style="text-align:left;"><strong>배경이 투명한 PNG 형식 (정방형 1:1 비율)</strong> 업로드 권장. (PDF 출력 시 문서 배경과 자연스럽게 합성됨)</td></tr><tr><td style="text-align:left;"><strong>보관 구분</strong></td><td style="text-align:left;"><code>custody_type</code></td><td style="text-align:left;">• <strong>사내 보관 (<code>internal</code>)</strong>: 본사 금고 또는 현장 사무소 보관<br>• <strong>외부 교부 (<code>external</code>)</strong>: 토지용역사, 분양대행사, 법무사 등 외부 위임처 교부</td></tr><tr><td style="text-align:left;"><strong>실물 보관처 / 수임자</strong></td><td style="text-align:left;"><code>custodian</code></td><td style="text-align:left;">실물 도장 보관 위치 및 수임자 (예: <em>본사 재경팀 금고</em>, <em>(주)개발컨설팅 김실장</em>)</td></tr><tr><td style="text-align:left;"><strong>사내 총괄 관리책임자</strong></td><td style="text-align:left;"><code>internal_manager</code></td><td style="text-align:left;">외부 교부 시에도 본사에서 교부/회수를 책임지는 정규직 관리자 (<code>Staff</code>) 지정</td></tr><tr><td style="text-align:left;"><strong>유효 기간 / 만료일</strong></td><td style="text-align:left;"><code>valid_from</code> / <code>valid_until</code></td><td style="text-align:left;">외부 용역 계약 기간에 따른 인감 교부 및 회수 예정 기한 관리</td></tr><tr><td style="text-align:left;"><strong>전결 직책 자격</strong></td><td style="text-align:left;"><code>final_approval_duty</code></td><td style="text-align:left;"><strong>🌟 핵심 통제 기준</strong>: 이 인장이 날인되기 위해 필요한 <strong>최소 최종 전결 직책</strong> 지정<br>• <code>팀장/현장소장</code>: 현장 책임자 승인으로 결재 종결 가능<br>• <code>미지정 (빈칸)</code>: 대표이사까지 결재선이 반드시 상신됨</td></tr><tr><td style="text-align:left;"><strong>연동 전결 결재선</strong></td><td style="text-align:left;"><code>route_template</code></td><td style="text-align:left;"><strong>🔒 필수 안전장치</strong>: 부서장/현장 직인(<code>DEPT_SEAL</code>)을 전자결재 공문에 사용하려면, 해당 책임자가 최종 전결권자로 지정된 <strong>수동 결재선 템플릿</strong>을 반드시 연동해야 합니다. 미연동 시 전자결재 기안 화면의 인장 목록에서 자동 제외됩니다.</td></tr><tr><td style="text-align:left;"><strong>사용 여부</strong></td><td style="text-align:left;"><code>is_active</code></td><td style="text-align:left;">폐기되거나 분실/회수된 인장은 체크를 해제하여 시스템 사용을 즉시 중단 처리합니다.</td></tr></tbody></table><h2 id="인장-종류별-결재선-분기-메커니즘" tabindex="-1">인장 종류별 결재선 분기 메커니즘 <a class="header-anchor" href="#인장-종류별-결재선-분기-메커니즘" aria-label="Permalink to &quot;인장 종류별 결재선 분기 메커니즘&quot;">​</a></h2><p>단일한 공문서 기안 양식 내에서도 관리부서가 사전에 지정한 인장의 전결 기준에 따라 결재선이 지능적으로 자동 분기됩니다.</p><h3 id="_1-대표이사-법인인감-corp-seal" tabindex="-1">1. 대표이사 법인인감 (<code>CORP_SEAL</code>) <a class="header-anchor" href="#_1-대표이사-법인인감-corp-seal" aria-label="Permalink to &quot;1. 대표이사 법인인감 (`CORP_SEAL`)&quot;">​</a></h3><ul><li><strong>설정 기준</strong>: <code>전결 직책 자격</code>을 **미지정(빈칸)**으로 보관합니다.</li><li><strong>작동 원리</strong>: 기안자가 해당 인장을 선택하면 시스템은 자동으로 결재선을 대표이사까지 필수 상신하도록 강제하며, <strong>대표이사의 최종 승인이 완료되기 전에는 어떠한 경우에도 인장이 날인되지 않습니다.</strong></li></ul><h3 id="_2-프로젝트-직인-부서장-직인-dept-seal" tabindex="-1">2. 프로젝트 직인 / 부서장 직인 (<code>DEPT_SEAL</code>) <a class="header-anchor" href="#_2-프로젝트-직인-부서장-직인-dept-seal" aria-label="Permalink to &quot;2. 프로젝트 직인 / 부서장 직인 (`DEPT_SEAL`)&quot;">​</a></h3><ul><li><strong>설정 기준</strong>: **사내 총괄 관리책임자(<code>internal_manager</code>)**와 <strong>연동 전결 결재선(<code>route_template</code>)</strong> 설정이 필수입니다.</li><li><strong>전자결재 발송 시</strong>: 해당 책임자가 최종 전결권자인 결재선 템플릿이 연결된 인장만 기안 화면에 표시되며, 상신 시 해당 전결 결재선이 자동 적용됩니다.</li><li><strong>수동 직접 발송 시</strong>: 인장 선택 시 등록된 책임자의 직책과 성명(예: <em>본부장 홍길동</em>)이 발송자 명의에 고정 반영되어 권한 없는 자의 명의 도용을 원천 차단합니다.</li></ul><h2 id="💡-관리부서-실무-유의사항" tabindex="-1">💡 관리부서 실무 유의사항 <a class="header-anchor" href="#💡-관리부서-실무-유의사항" aria-label="Permalink to &quot;💡 관리부서 실무 유의사항&quot;">​</a></h2><ul><li><strong>실물 인감 날인 후 스캔본 보관 절차</strong>: 대외 관공서 제출용으로 종이 출력 후 실물 인감을 직접 날인하여 발송하는 경우, 공문 기안 시 인장을 <code>인장 미선택 / (직인생략 / 출력 후 실물날인)</code>으로 상신하도록 안내하십시오. 발송 완료 후에는 실제 날인된 종이 문서를 스캔하여 <strong>스캔본(PDF)으로 재등록</strong>해야 공문 대장의 법적 증빙 효력이 유지됩니다.</li><li><strong>발송 완료 후 증빙 위변조 방지</strong>: 대외 발송이 완료된 공문서는 시스템 내 PDF 재생성(템플릿 덮어쓰기)이 완전히 잠깁니다. 이미 발송된 공문의 스캔본을 불가피하게 교체해야 할 때는 일반 사용자 권한으로는 불가능하며, 관리부서(슈퍼유저/워크매니저)가 사유를 확인한 후 직접 처리해야 합니다.</li><li><strong>투명 배경 인장 이미지 가공</strong>: 도장 이미지를 등록할 때 흰색 배경이 남아있으면 공문서 텍스트나 하단 테두리를 가려 서식이 조잡해 보일 수 있습니다. 포토샵이나 배경 제거 도구를 활용하여 도장 테두리 바깥이 투명한 PNG 파일로 등록해 주십시오.</li></ul>',11))])}const D=d(g,[["render",c]]);export{x as __pageData,D as default};
